import { useState } from 'react';
import './styles.css';
type Row = { id: string; name: string; team: string; tenure: number };
const rows: Row[] = [
  { id: 'a', name: 'Ana', team: 'Platform', tenure: 4 }, { id: 'b', name: 'Ben', team: 'Data', tenure: 2 },
  { id: 'c', name: 'Chloe', team: 'Design', tenure: 6 }, { id: 'd', name: 'Dev', team: 'Platform', tenure: 1 }, { id: 'e', name: 'Eli', team: 'Data', tenure: 3 },
];
export function TeamTable() {
  const [sortKey, setSortKey] = useState<keyof Row>('name');
  const sorted = [...rows].sort((x, y) => (x[sortKey] > y[sortKey] ? 1 : -1));
  return (
    <table>
      <thead><tr>{(['name', 'team', 'tenure'] as (keyof Row)[]).map(k => <th key={k} onClick={() => setSortKey(k)}>{k}</th>)}</tr></thead>
      <tbody>{sorted.map(r => <tr key={r.id}><td>{r.name}</td><td>{r.team}</td><td>{r.tenure}</td></tr>)}</tbody>
    </table>
  );
}

